// Assignments (HW1–HW3): every question with its diagram and a detailed worked answer.
// Answers are built with S(): approach, numbered steps, boxed final answer, optional "watch out" note.
// Needs practice.js loaded first (it defines R = String.raw and FIGS).
const S = (idea, steps, ans, tip) =>
  `<div class="idea"><b>Approach.</b> ${idea}</div>` +
  steps.map((t,i)=>`<div class="stp"><span>${i+1}</span><div>${t}</div></div>`).join('') +
  `<div class="final"><b>Answer.</b> ${ans}</div>` +
  (tip ? `<div class="atip"><b>Watch out.</b> ${tip}</div>` : '');

Object.assign(FIGS,{
 "a2:0":["sl4c"],"a2:6":["a2q7"],"a2:7":["a2q8"],"a2o:2":["a2o3"],"a2p:0":["a2p1"],"a2p:1":["a2p2"],
 "a3:3":["a3q4"],"a3:6":["a3q7"],"a3o:0":["a3o1"],
});

const ASSIGN = [
{id:"hw1", title:"Homework 1 · vectors and electric field", icon:"1️⃣", c:["#6366f1","#8b5cf6"], note:"Detailed solutions to the HW1 questions. Ticks are shared with the Practice tab, which has the short versions.", items:[
 {pid:"hw:0", src:"HW1 Q1–2 · vectors", q:R`<b>Q1.</b> An equilateral triangle lies in the $xy$-plane with its centroid at the origin and one vertex (A) on the $+y$ axis. (a) Find unit vectors from the origin to the three vertices. (b) Find unit vectors from the origin to the three sides, meeting each side at right angles.<br><b>Q2.</b> $\vec v$ goes from the origin to point B on a straight line through the origin. Which point could be the end of $2\vec v$?`,
  a:S(R`A unit vector in the direction at angle $\theta$ from the $+x$ axis is $(\cos\theta,\sin\theta)$, so everything reduces to finding the angles.`,[
   R`<b>Vertices.</b> The centroid is the centre of the triangle, so the three vertices are equally spaced around the origin, $360°/3=120°$ apart. Vertex A is at $90°$, so the others are at $90°+120°=210°$ (C, lower left) and $90°-120°=-30°$ (B, lower right).`,
   R`Write each unit vector as $(\cos\theta,\sin\theta)$:<br>$\hat a_A=(\cos90°,\sin90°)=(0,1)$<br>$\hat a_B=(\cos(-30°),\sin(-30°))=(\tfrac{\sqrt3}{2},-\tfrac12)$<br>$\hat a_C=(\cos210°,\sin210°)=(-\tfrac{\sqrt3}{2},-\tfrac12)$<br>Check: $\tfrac34+\tfrac14=1$ ✓ (each has length 1).`,
   R`<b>Sides.</b> In an equilateral triangle each median is also an altitude, so the perpendicular from the centroid to a side lies along the median through the <i>opposite</i> vertex, but pointing the other way (away from that vertex, toward the side).`,
   R`So the side directions are the negatives of the vertex vectors:<br>to side BC (bottom, point Q): $-\hat a_A=(0,-1)$<br>to side AC (left, point R): $-\hat a_B=(-\tfrac{\sqrt3}{2},\tfrac12)$, i.e. at $150°$<br>to side AB (right, point P): $-\hat a_C=(\tfrac{\sqrt3}{2},\tfrac12)$, i.e. at $30°$`,
   R`<b>Q2.</b> $2\vec v$ points the same way as $\vec v$ but is twice as long. In the figure, A is about twice as far from the origin as B along the same ray, so doubling $\vec v$ lands on A.`],
   R`(a) $(0,1)$, $(\tfrac{\sqrt3}{2},-\tfrac12)$, $(-\tfrac{\sqrt3}{2},-\tfrac12)$. (b) $(0,-1)$, $(-\tfrac{\sqrt3}{2},\tfrac12)$, $(\tfrac{\sqrt3}{2},\tfrac12)$. Q2: <b>point A</b>.`,
   R`C lies between B and the origin on the same side, so it is <i>shorter</i> than $\vec v$. D, E, F are on the opposite side of the origin, so they would be $-\vec v$, $-2\vec v$, etc.`)},
 {pid:"hw:1", src:"HW1 Q3 · field vs force", q:R`Two small charges, $q$ and $-4q$, are placed at the same distance from a positive point charge $Q$. Choose the correct statements about the electric field experienced by the small charges.<br>A. Same magnitude &nbsp; B. $-4q$ feels a greater field &nbsp; C. Both fields point towards $Q$ &nbsp; D. Both fields point away from $Q$ &nbsp; E. $q$ away, $-4q$ towards`,
  a:S(R`The electric field at a point is created by the <i>source</i> charge only. The small charge is just a probe that feels a force $\vec F=q\vec E$.`,[
   R`The source is $Q$, so at distance $r$ the field is $\vec E=\dfrac{Q}{4\pi\epsilon_0r^2}\hat r$, the same at every point on the circle of radius $r$. It does not depend on $q$ or $-4q$.`,
   R`Therefore both small charges sit in a field of equal magnitude (A is true) and the field points radially <i>away</i> from the positive charge $Q$ (D is true).`,
   R`The sign of the small charge matters only for the <i>force</i>: $\vec F=q\vec E$ points along $\vec E$ for $q$, but opposite to $\vec E$ (toward $Q$, and 4 times larger) for $-4q$.`],
   R`<b>A and D.</b>`,
   R`B, C and E mix up the field with the force on the charge. “The field experienced by a charge” is the field at its location.`)},
 {pid:"hw:2", src:"HW1 Q4 = Hayt 2.5 · field of two charges", q:R`$Q_1=25$ nC is at $P_1(4,-2,7)$ and $Q_2=60$ nC is at $P_2(-3,4,-2)$ (metres), free space. (a) Find $\vec E$ at $P_3(1,2,3)$. (b) At what point on the $y$-axis is $E_x=0$?`,
  a:S(R`Superposition: $\vec E=\sum\dfrac{kQ_i\,\vec R_i}{|\vec R_i|^3}$ with $\vec R_i$ drawn from charge $i$ to the field point, and $k=\dfrac1{4\pi\epsilon_0}=8.99\times10^9$.`,[
   R`<b>(a) Vectors.</b> $\vec R_1=P_3-P_1=(1-4,\,2+2,\,3-7)=(-3,4,-4)$, so $|\vec R_1|=\sqrt{41}=6.403$ and $|\vec R_1|^3=262.5$.<br>$\vec R_2=P_3-P_2=(1+3,\,2-4,\,3+2)=(4,-2,5)$, so $|\vec R_2|=\sqrt{45}=6.708$ and $|\vec R_2|^3=301.9$.`,
   R`<b>Each field.</b> $kQ_1=(8.99\times10^9)(25\times10^{-9})=224.7$ and $kQ_2=539.3$.<br>$\vec E_1=\dfrac{224.7}{262.5}(-3,4,-4)=0.856(-3,4,-4)=(-2.57,\;3.42,\;-3.42)$<br>$\vec E_2=\dfrac{539.3}{301.9}(4,-2,5)=1.786(4,-2,5)=(7.14,\;-3.57,\;8.93)$`,
   R`<b>Add as vectors:</b> $\vec E=(-2.57+7.14,\;3.42-3.57,\;-3.42+8.93)=(4.58,\,-0.15,\,5.51)$ V/m.`,
   R`<b>(b) Points on the $y$-axis:</b> $(0,y,0)$. Then $\vec R_1=(-4,\,y+2,\,-7)$ with $|\vec R_1|^2=65+(y+2)^2$, and $\vec R_2=(3,\,y-4,\,2)$ with $|\vec R_2|^2=13+(y-4)^2$.`,
   R`Only the $x$-components matter: $E_x=-\dfrac{kQ_1(4)}{|\vec R_1|^3}+\dfrac{kQ_2(3)}{|\vec R_2|^3}=0\ \Rightarrow\ \dfrac{100}{|\vec R_1|^3}=\dfrac{180}{|\vec R_2|^3}\ \Rightarrow\ \dfrac{|\vec R_2|^3}{|\vec R_1|^3}=1.8$.`,
   R`Take the cube root and square: $\dfrac{|\vec R_2|^2}{|\vec R_1|^2}=1.8^{2/3}=1.480$. So $13+(y-4)^2=1.480\,[65+(y+2)^2]$, which simplifies to $0.480y^2+13.92y+73.1=0$.`,
   R`Quadratic formula: $y=\dfrac{-13.92\pm\sqrt{13.92^2-4(0.480)(73.1)}}{2(0.480)}=\dfrac{-13.92\pm7.31}{0.960}$, giving $y=-6.89$ or $y=-22.1$.`],
   R`(a) $\vec E=\mathbf{4.58\,\hat a_x-0.15\,\hat a_y+5.51\,\hat a_z}$ V/m. (b) $E_x=0$ at $\mathbf{y=-6.89}$ m and $\mathbf{y=-22.1}$ m.`,
   R`Use $\vec R$ = (field point) − (source). Swapping it flips every field direction.`)},
 {pid:"hw:3", src:"HW1 Q5 · cube of charges", q:R`Eight identical charges $Q$ sit at the corners of a cube of side $a$ (one at the origin, three at $(a,0,0)$, $(0,a,0)$, $(0,0,a)$). Find the total vector force on the charge at $P(a,a,a)$ in free space.`,
  a:S(R`Put $P$ at the corner $(a,a,a)$ and sort the other seven charges by distance. Each pushes $P$ directly away from itself with $F=kQ^2/d^2$. By symmetry the net force is along $(1,1,1)$.`,[
   R`<b>3 charges at distance $a$</b> (the neighbours along the edges): $(a,a,0)$, $(a,0,a)$, $(0,a,a)$. Each force has magnitude $F_0=kQ^2/a^2$ and points along $+z$, $+y$, $+x$ respectively, so together: $F_0(1,1,1)$.`,
   R`<b>3 charges at distance $a\sqrt2$</b> (face diagonals): $(a,0,0)$, $(0,a,0)$, $(0,0,a)$. Each has magnitude $\dfrac{kQ^2}{2a^2}$. The force from $(a,0,0)$ points along $\dfrac{(0,1,1)}{\sqrt2}$, and similarly for the others. Adding the three unit directions: $\dfrac{(0,1,1)+(1,0,1)+(1,1,0)}{\sqrt2}=\dfrac{(2,2,2)}{\sqrt2}$, so the total is $\dfrac{kQ^2}{2a^2}\cdot\dfrac{2}{\sqrt2}(1,1,1)=\dfrac{F_0}{\sqrt2}(1,1,1)$.`,
   R`<b>1 charge at distance $a\sqrt3$</b> (the origin): magnitude $\dfrac{kQ^2}{3a^2}$ along $\dfrac{(1,1,1)}{\sqrt3}$, i.e. $\dfrac{F_0}{3\sqrt3}(1,1,1)$.`,
   R`<b>Add:</b> $\vec F=F_0\Big(1+\dfrac1{\sqrt2}+\dfrac1{3\sqrt3}\Big)(1,1,1)=1.90\,F_0\,(1,1,1)$.`],
   R`$$\vec F=\frac{Q^2}{4\pi\epsilon_0a^2}\Big(1+\tfrac1{\sqrt2}+\tfrac1{3\sqrt3}\Big)(\hat a_x+\hat a_y+\hat a_z)\approx\frac{1.90\,Q^2}{4\pi\epsilon_0a^2}(\hat a_x+\hat a_y+\hat a_z)$$ with magnitude $3.29\,\dfrac{Q^2}{4\pi\epsilon_0a^2}$.`,
   R`Group by distance before you start, and use the symmetry to skip most of the component work. Don't forget that forces from the face-diagonal charges have <i>two</i> non-zero components each.`)},
 {pid:"hw:4", src:"HW1 Q6 · charge from field", q:R`A charge $Q$ is at the origin. The field at $(0,3\text{ m})$ has magnitude 1000 N/C and points <i>toward</i> the origin. Find $Q$ (use $k=9\times10^9$ N·m²/C²).`,
  a:S(R`Use $E=k|Q|/r^2$ for the size, and the direction of the field to find the sign.`,[
   R`<b>Sign.</b> The field points toward the charge, and field lines point away from positive charges and toward negative ones. So $Q<0$.`,
   R`<b>Size.</b> $|Q|=\dfrac{Er^2}{k}=\dfrac{(1000)(3)^2}{9\times10^9}=\dfrac{9000}{9\times10^9}=10^{-6}\ \text{C}$.`],
   R`$Q=\mathbf{-1.0\ \mu C}$.`,
   R`The distance is 3 m (the point is at $(0,3)$ and the charge at the origin), and it is squared.`)},
 {pid:"hw:5", src:"HW1 Q7 · force on an α particle", q:R`An α particle (charge $+2e$) passes along the perpendicular bisector of the line joining two nuclei (each $+e$, separation $d$). Ignoring the electrons and the nuclei's motion, where is the force on the α particle largest?`,
  a:S(R`Find the net field of the two nuclei at distance $x$ from the molecule's centre along the bisector, then maximise it. The force is $2eE$, so the maximum of $F$ is where $E$ is maximum.`,[
   R`<b>Geometry.</b> Each nucleus is a distance $s=\sqrt{x^2+d^2/4}$ from the α particle. Each produces a field $\dfrac{ke}{s^2}$ directed away from that nucleus.`,
   R`<b>Components.</b> The parts parallel to the line joining the nuclei cancel (the nuclei are symmetric). The parts along the path add; each has a factor $\dfrac xs$. So $$E(x)=2\cdot\frac{ke}{s^2}\cdot\frac xs=\frac{2kex}{(x^2+d^2/4)^{3/2}}.$$`,
   R`<b>Maximise.</b> $\dfrac{dE}{dx}=2ke\Big[(x^2+\tfrac{d^2}{4})^{-3/2}-3x^2(x^2+\tfrac{d^2}{4})^{-5/2}\Big]=0$. Multiply by $(x^2+\tfrac{d^2}4)^{5/2}$: $x^2+\tfrac{d^2}{4}=3x^2$, so $x^2=\tfrac{d^2}{8}$.`,
   R`<b>Check it is a maximum.</b> $E=0$ at $x=0$ (by symmetry) and $E\to0$ as $x\to\infty$ ($\sim1/x^2$), so the single stationary point must be the maximum. Its value is $E_{max}\approx3.08\,\dfrac{ke}{d^2}$.`],
   R`Maximum force at $x=\dfrac{d}{2\sqrt2}=0.354\,d$ from the centre (on either side of it), where $F_{max}=2eE_{max}\approx6.2\,\dfrac{ke^2}{d^2}$.`,
   R`The force is zero at the centre itself, even though the nuclei are closest there, because their fields cancel.`)},
 {pid:"hw:6", src:"HW1 Q8 · linear quadrupole", q:R`The charge distribution $(-q,+2q,-q)$, equally spaced by $l$, is a linear electric quadrupole. Show that on its axis, at a distance $r\gg l$ from the centre, $E=\dfrac{3Q}{4\pi\epsilon_0r^4}$ with $Q=2ql^2$.`,
  a:S(R`Add the three point-charge fields on the axis, then use a Taylor (binomial) expansion in the small ratio $\epsilon=l/r$. Terms of order $1/r^2$ and $1/r^3$ cancel, leaving $1/r^4$.`,[
   R`<b>Set up.</b> Put $+2q$ at the centre. The two $-q$ charges are at $\pm l$. For the point $P$ on the axis at distance $r$ (to the right), distances are $r$ (to $2q$), $r-l$ (to the near $-q$) and $r+l$ (to the far $-q$). All fields lie along the axis: $$E=k\Big[\frac{2q}{r^2}-\frac{q}{(r-l)^2}-\frac{q}{(r+l)^2}\Big]$$`,
   R`<b>Expand.</b> Write $\dfrac1{(r\mp l)^2}=\dfrac1{r^2}(1\mp\epsilon)^{-2}$ and use $(1+x)^{-2}\approx1-2x+3x^2$ for small $x$:<br>$(1-\epsilon)^{-2}\approx1+2\epsilon+3\epsilon^2$ and $(1+\epsilon)^{-2}\approx1-2\epsilon+3\epsilon^2$.`,
   R`<b>Add the two.</b> The odd terms cancel: $(1-\epsilon)^{-2}+(1+\epsilon)^{-2}\approx2+6\epsilon^2$.`,
   R`<b>Combine.</b> $E=\dfrac{kq}{r^2}\big[2-(2+6\epsilon^2)\big]=-\dfrac{6kq\epsilon^2}{r^2}=-\dfrac{6kql^2}{r^4}$.<br>Since $k=\dfrac1{4\pi\epsilon_0}$ and $Q=2ql^2$: $6kql^2=\dfrac{3(2ql^2)}{4\pi\epsilon_0}=\dfrac{3Q}{4\pi\epsilon_0}$.`],
   R`$|E|=\dfrac{3Q}{4\pi\epsilon_0r^4}$, directed toward the quadrupole (the minus sign: the near $-q$ wins). ✓`,
   R`A point charge falls as $1/r^2$, a dipole as $1/r^3$, a quadrupole as $1/r^4$. If your result has the wrong power, you dropped a term in the expansion.`)},
 {pid:"a1:opt9", src:"HW1 Optional 9 · coplanar vectors", q:R`$\mathbf A+\mathbf B+\mathbf C=0$, with the three vectors drawn from a common origin. (a) Must they be coplanar? (b) If $\mathbf A+\mathbf B+\mathbf C+\mathbf D=0$, must the four vectors be coplanar?`,
  a:S(R`Choose a coordinate system that makes the algebra trivial, then look at the leftover component of the sum.`,[
   R`<b>(a)</b> Two vectors always span a plane (if they are not parallel). Orient the axes so that $\mathbf A$ and $\mathbf B$ lie in the $xy$-plane: $A_z=B_z=0$.`,
   R`The $z$-component of $\mathbf A+\mathbf B+\mathbf C=0$ reads $A_z+B_z+C_z=0$, so $C_z=0$. So $\mathbf C$ also lies in the $xy$-plane: all three are coplanar.`,
   R`<b>(b)</b> Again put $\mathbf A,\mathbf B$ in the $xy$-plane. Now the $z$-condition is only $C_z+D_z=0$.`,
   R`That allows $C_z=-D_z\ne0$. Example: $\mathbf A=(1,0,0)$, $\mathbf B=(0,1,0)$, $\mathbf C=(-1,0,1)$, $\mathbf D=(0,-1,-1)$ sum to zero, but $\mathbf C$ and $\mathbf D$ leave the plane.`],
   R`(a) <b>Yes</b>, always coplanar. (b) <b>No</b>, four vectors summing to zero need not be coplanar.`)},
 {pid:"hw:7", src:"HW1 Optional 10 · triangle of charges", q:R`Charges $q_1=1.0\ \mu$C, $q_2=3.0\ \mu$C and $q_3=-1.0\ \mu$C sit at the vertices of an equilateral triangle of side 2 cm ($q_2$ at the top, $q_1$ bottom left, $q_3$ bottom right). (1) Which charge feels the largest net force? (2) Find the force on $q_2$.`,
  a:S(R`Three pair forces, each from $F=k|q_iq_j|/r^2$. Decide each one's direction (like charges repel, unlike attract), resolve into $x,y$ components, and add.`,[
   R`<b>Magnitudes</b> ($r=0.02$ m, so $r^2=4\times10^{-4}$): $F_{12}=\dfrac{k(1)(3)\times10^{-12}}{4\times10^{-4}}=67.4$ N, $F_{23}=\dfrac{k(3)(1)\times10^{-12}}{4\times10^{-4}}=67.4$ N, $F_{13}=\dfrac{k(1)(1)\times10^{-12}}{4\times10^{-4}}=22.5$ N.`,
   R`<b>Directions.</b> $q_1,q_2$ are both positive: they repel. $q_2,q_3$ attract. $q_1,q_3$ attract. The triangle's sides are at $0°$, $60°$ and $120°$, so each force has components with $\cos60°=\tfrac12$ and $\sin60°=\tfrac{\sqrt3}2$.`,
   R`<b>On $q_2$ (top).</b> From $q_1$: repelled, directed up and to the right: $67.4(\tfrac12,\tfrac{\sqrt3}2)$. From $q_3$: attracted, directed down and to the right: $67.4(\tfrac12,-\tfrac{\sqrt3}2)$. Sum: the $y$ parts cancel, the $x$ parts add: $\vec F_2=(67.4,\,0)$ N.`,
   R`<b>On $q_1$ (bottom left).</b> From $q_2$: repelled, down and to the left: $67.4(-\tfrac12,-\tfrac{\sqrt3}2)=(-33.7,-58.4)$. From $q_3$: attracted along $+x$: $(22.5,0)$. Sum $=(-11.2,-58.4)$, $|\vec F_1|=59.5$ N.`,
   R`<b>On $q_3$ (bottom right).</b> From $q_2$: attracted, up and to the left: $67.4(-\tfrac12,\tfrac{\sqrt3}2)=(-33.7,58.4)$. From $q_1$: attracted along $-x$: $(-22.5,0)$. Sum $=(-56.2,58.4)$, $|\vec F_3|=81.0$ N.`],
   R`(1) $q_3$ feels the largest force, $\mathbf{81.0}$ N (vs 67.4 N on $q_2$, 59.5 N on $q_1$). (2) On $q_2$: $\mathbf{67.4}$ N, parallel to the base, pointing toward the $q_3$ side.`,
   R`Force on $q_3$ from $q_1$ is an <i>attraction</i>, so it points <i>toward</i> $q_1$ (left), not away.`)},
 {pid:"a1:opt11", src:"HW1 Optional 11 · hydrogen atom", q:R`In a classical hydrogen atom the electron orbits the proton at $r=0.529\times10^{-10}$ m. ($m_p=1.67\times10^{-27}$ kg, $m_e=9.11\times10^{-31}$ kg, $e=1.60\times10^{-19}$ C, $G=6.67\times10^{-11}$ N·m²/kg².) Find (1) the Coulomb force and the gravitational force on the electron, (2) how many times larger the Coulomb force is, (3) the electron's speed.`,
  a:S(R`Compare the two inverse-square forces, then set the Coulomb force equal to the centripetal force for a circular orbit.`,[
   R`<b>Coulomb force:</b> $F_C=\dfrac{ke^2}{r^2}=\dfrac{(9\times10^9)(1.60\times10^{-19})^2}{(0.529\times10^{-10})^2}=\dfrac{2.30\times10^{-28}}{2.80\times10^{-21}}=8.2\times10^{-8}$ N.`,
   R`<b>Gravity:</b> $F_G=\dfrac{Gm_em_p}{r^2}=\dfrac{(6.67\times10^{-11})(9.11\times10^{-31})(1.67\times10^{-27})}{2.80\times10^{-21}}=3.6\times10^{-47}$ N.`,
   R`<b>Ratio:</b> $\dfrac{F_C}{F_G}=\dfrac{8.2\times10^{-8}}{3.6\times10^{-47}}\approx2.3\times10^{39}$.`,
   R`<b>Speed.</b> A circular orbit needs $F_C=\dfrac{m_ev^2}{r}$, so $v=\sqrt{\dfrac{F_Cr}{m_e}}=\sqrt{\dfrac{(8.2\times10^{-8})(0.529\times10^{-10})}{9.11\times10^{-31}}}=\sqrt{4.8\times10^{12}}=2.19\times10^6$ m/s.`],
   R`$F_C\approx8.2\times10^{-8}$ N, $F_G\approx3.6\times10^{-47}$ N, ratio $\approx2.3\times10^{39}$ (gravity is negligible), $v\approx2.2\times10^6$ m/s (about 0.7% of the speed of light).`)},
 {pid:"hw:8", src:"HW1 Optional 12 · square of charges", q:R`Charges $Q$ sit at two opposite corners of a square and $q$ at the other two. If the net force on each $Q$ is zero, how are $Q$ and $q$ related?`,
  a:S(R`Take the charge $Q$ at one corner and add the three forces on it. By the square's symmetry the net force lies along the diagonal through it, so you only need the component along that diagonal.`,[
   R`Let the square have side $a$. The other $Q$ is at the opposite corner, distance $a\sqrt2$ along the diagonal. Its force on our $Q$ has magnitude $\dfrac{kQ^2}{(a\sqrt2)^2}=\dfrac{kQ^2}{2a^2}$ and points <i>away</i> from it along the diagonal (two equal charges repel).`,
   R`The two $q$ charges are adjacent corners, distance $a$ from our $Q$. Each exerts a force $\dfrac{kQq}{a^2}$ along an edge. The edges make $45°$ with the diagonal, so each contributes $\dfrac{kQq}{a^2}\cos45°$ along the diagonal. Together: $\dfrac{2kQq}{a^2}\cdot\dfrac1{\sqrt2}=\dfrac{\sqrt2\,kQq}{a^2}$.`,
   R`The components perpendicular to the diagonal cancel by symmetry. For zero net force along the diagonal, the $q$-forces must point the opposite way from the $Q$–$Q$ repulsion: $$\frac{kQ^2}{2a^2}+\frac{\sqrt2\,kQq}{a^2}=0\ \Rightarrow\ \frac Q2+\sqrt2\,q=0$$`],
   R`$\mathbf{Q=-2\sqrt2\,q\approx-2.83\,q}$: the two charges must have opposite signs (the $q$'s pull the $Q$'s together, balancing their mutual repulsion).`,
   R`This makes the force on each $Q$ zero, but not on the $q$'s. Zero force on a $q$ would need $q=-2\sqrt2\,Q$ by the same working, which contradicts $Q=-2\sqrt2\,q$. So the four charges can't all be in equilibrium on their own.`)},
]},

{id:"hw2", title:"Homework 2 · Gauss's law, work and potential", icon:"2️⃣", c:["#0ea5e9","#06b6d4"], note:"The eight main questions with detailed solutions. Optional practice (with the provided solutions, expanded) follows.", items:[
 {pid:"a2:0", src:"HW2 Q1 · Gauss (integral)", q:R`Two infinite coaxial cylindrical shells have radii $a$ and $b$ ($b>a$) and surface charge densities $\sigma_{s1}$ and $\sigma_{s2}$. Find $\mathbf E$ everywhere and plot $|E|$ against $r$.`,
  a:S(R`Cylindrical symmetry ⇒ use Gauss's law with a coaxial cylinder: $\oint\vec E\cdot d\vec S=Q_{enc}/\epsilon_0$.`,[
   R`<b>Symmetry.</b> The charges are infinitely long and uniform around the axis, so $\vec E$ is purely radial and depends only on $r$. Choose a coaxial Gaussian cylinder of radius $r$ and length $l$.`,
   R`<b>Flux.</b> The two end caps have $\vec E\perp d\vec S$ (no flux). On the curved side $E$ is constant and parallel to $d\vec S$, so $\oint\vec E\cdot d\vec S=E\,(2\pi rl)$.`,
   R`<b>Region $r<a$:</b> the cylinder encloses no charge, so $E\,(2\pi rl)=0$ and $E=0$.`,
   R`<b>Region $a<r<b$:</b> only the inner shell is inside. Its charge in length $l$ is (density)×(area) $=\sigma_{s1}(2\pi al)$. So $E\,2\pi rl=\dfrac{\sigma_{s1}2\pi al}{\epsilon_0}\Rightarrow E=\dfrac{\sigma_{s1}a}{\epsilon_0r}$.`,
   R`<b>Region $r>b$:</b> both shells are inside: $Q_{enc}=\sigma_{s1}2\pi al+\sigma_{s2}2\pi bl$, so $E=\dfrac{\sigma_{s1}a+\sigma_{s2}b}{\epsilon_0r}$.`,
   R`<b>Plot.</b> $|E|=0$ for $r<a$; at $r=a$ it jumps up by $\sigma_{s1}/\epsilon_0$ (the surface-charge jump), then decays as $1/r$; at $r=b$ it jumps by $\sigma_{s2}/\epsilon_0$ (down if $\sigma_{s2}<0$) and continues as $1/r$ with the new coefficient.`],
   R`$E=0\ (r<a)$; $\ E=\dfrac{\sigma_{s1}a}{\epsilon_0r}\hat r\ (a<r<b)$; $\ E=\dfrac{\sigma_{s1}a+\sigma_{s2}b}{\epsilon_0r}\hat r\ (r>b)$.`,
   R`The enclosed charge uses the area of the <i>curved surface of the shell</i>, $2\pi al$, not a cross-section area.`)},
 {pid:"a2:1", src:"HW2 Q2 · Gauss (integral)", q:R`The charge density in cylindrical coordinates is $\rho_v=50\,r\,e^{-r}$ C/m³. Apply Gauss's law to find $\mathbf E$.`,
  a:S(R`The density depends only on $r$, so $\vec E$ is radial. A coaxial Gaussian cylinder gives $E(2\pi rl)=Q_{enc}/\epsilon_0$, where $Q_{enc}$ comes from integrating $\rho_v$ through shells.`,[
   R`<b>Enclosed charge.</b> A thin cylindrical shell of radius $r'$, thickness $dr'$ and length $l$ has volume $2\pi r'l\,dr'$ and charge $\rho_v\,dV$. So $$Q_{enc}=\int_0^r(50r'e^{-r'})(2\pi r'l)\,dr'=100\pi l\int_0^rr'^2e^{-r'}dr'.$$`,
   R`<b>The integral</b> (integrate by parts twice): $\int r'^2e^{-r'}dr'=-e^{-r'}(r'^2+2r'+2)$. Check by differentiating: $\dfrac{d}{dr'}\big[-e^{-r'}(r'^2+2r'+2)\big]=e^{-r'}(r'^2+2r'+2)-e^{-r'}(2r'+2)=r'^2e^{-r'}$ ✓.<br>Between $0$ and $r$: $\ 2-e^{-r}(r^2+2r+2)$.`,
   R`<b>Gauss.</b> $E(2\pi rl)=\dfrac{100\pi l}{\epsilon_0}\big[2-e^{-r}(r^2+2r+2)\big]$. Cancel $2\pi l$: $$E=\frac{50}{\epsilon_0r}\Big[2-e^{-r}(r^2+2r+2)\Big].$$`,
   R`<b>Sanity checks.</b> As $r\to0$ the bracket $\to0$ faster than $r$, so $E\to0$ (no charge enclosed). As $r\to\infty$, $E\to\dfrac{100}{\epsilon_0r}$, which is the field of a line charge $\lambda=200\pi$ C/m $=2\pi\int_0^\infty50r^2e^{-r}dr$ ✓.`],
   R`$$\vec E=\frac{50}{\epsilon_0\,r}\Big[2-e^{-r}(r^2+2r+2)\Big]\hat a_r\ \text{V/m}$$`,
   R`The volume element in a cylinder is $r\,dr\,d\phi\,dz$: don't forget the extra factor of $r'$ from the area $2\pi r'l$.`)},
 {pid:"a2:2", src:"HW2 Q3 · Gauss (differential)", q:R`A cube in free space occupies $1<x,y,z<1.2$ m, with $\vec E=\dfrac1{\epsilon_0}\big(2x^2y\,\hat x+3x^2y^2\,\hat y\big)$ V/m. (a) Use the integral form of Gauss's law to find the flux leaving the cube. (b) Evaluate $\nabla\cdot\vec E$ at the centre $(1.1,1.1,1.1)$. (c) Estimate $Q_{in}$ from the differential form and compare it with the exact value.`,
  a:S(R`Integral form: $Q_{in}=\epsilon_0\oint\vec E\cdot d\vec S$. Differential form: $\rho=\epsilon_0\nabla\cdot\vec E$, so for a small cube $Q\approx\epsilon_0(\nabla\cdot\vec E)\Delta v$. They should agree closely.`,[
   R`<b>(a) Which faces count.</b> $E_z=0$, so the faces $z=1$ and $z=1.2$ carry no flux. Each remaining face is a $0.2\times0.2$ square.`,
   R`<b>$x$-faces.</b> Outward normal is $+\hat x$ at $x=1.2$ and $-\hat x$ at $x=1$. $$\Phi_x=\frac1{\epsilon_0}\int_{z}\int_{y}\big[2(1.2)^2y-2(1)^2y\big]dy\,dz=\frac{2(0.44)}{\epsilon_0}\Big[\frac{y^2}{2}\Big]_1^{1.2}(0.2)=\frac{0.88(0.22)(0.2)}{\epsilon_0}=\frac{0.03872}{\epsilon_0}.$$`,
   R`<b>$y$-faces.</b> Normal $+\hat y$ at $y=1.2$ and $-\hat y$ at $y=1$. $$\Phi_y=\frac1{\epsilon_0}\int_z\int_x3x^2\big[(1.2)^2-(1)^2\big]dx\,dz=\frac{3(0.44)}{\epsilon_0}\Big[\frac{x^3}{3}\Big]_1^{1.2}(0.2)=\frac{1.32(0.2427)(0.2)}{\epsilon_0}=\frac{0.06406}{\epsilon_0}.$$`,
   R`<b>Total flux:</b> $\Phi_E=\dfrac{0.03872+0.06406}{\epsilon_0}=\dfrac{0.1028}{\epsilon_0}=1.16\times10^{10}$ V·m, so $Q_{in}=\epsilon_0\Phi_E=0.1028$ C.`,
   R`<b>(b) Divergence.</b> $\nabla\cdot\vec E=\dfrac{\partial E_x}{\partial x}+\dfrac{\partial E_y}{\partial y}+\dfrac{\partial E_z}{\partial z}=\dfrac{1}{\epsilon_0}\big(4xy+6x^2y+0\big)$. At $(1.1,1.1,1.1)$: $4(1.21)+6(1.331)=4.84+7.986=12.83$, so $\nabla\cdot\vec E=\dfrac{12.83}{\epsilon_0}$ V/m².`,
   R`<b>(c) Estimate.</b> $Q_{in}\approx\epsilon_0(\nabla\cdot\vec E)\Delta v=12.83\,(0.2)^3=0.1026$ C. Compare with the exact $0.1028$ C: the difference is about $0.2\%$, because the divergence barely changes across such a small cube.`],
   R`(a) $\Phi_E=0.1028/\epsilon_0=1.16\times10^{10}$ V·m ($Q_{in}=0.1028$ C). (b) $\nabla\cdot\vec E=12.83/\epsilon_0$. (c) $Q_{in}\approx0.1026$ C, matching the exact value to about 0.2%.`,
   R`Since $\vec E$ carries a $1/\epsilon_0$, the “flux” is in V·m; multiplying by $\epsilon_0$ turns it into coulombs.`)},
 {pid:"a2:3", src:"HW2 Q4 · Gauss (differential)", q:R`A radial field in free space is $\vec E_1=\dfrac{r\rho_0}{3\epsilon_0}\hat a_r$ ($r\le a$), $\vec E_2=\dfrac{(2a^3-r^3)\rho_0}{3\epsilon_0r^2}\hat a_r$ ($a\le r\le b$), $\vec E_3=\dfrac{(2a^3-b^3)\rho_0}{3\epsilon_0r^2}\hat a_r$ ($r\ge b$). (a) Find the volume charge density everywhere from $\nabla\cdot\vec E=\rho_v/\epsilon_0$. (b) Find the total charge $Q$ inside a sphere of radius $r>b$.`,
  a:S(R`For a purely radial field the divergence is $\nabla\cdot\vec E=\dfrac1{r^2}\dfrac{d}{dr}(r^2E_r)$ (the hint). Compute $r^2E_r$ in each region, differentiate, and multiply by $\epsilon_0$.`,[
   R`<b>Region $r\le a$:</b> $r^2E_1=\dfrac{\rho_0r^3}{3\epsilon_0}$. $\dfrac{d}{dr}=\dfrac{\rho_0r^2}{\epsilon_0}$. Divide by $r^2$: $\nabla\cdot\vec E=\dfrac{\rho_0}{\epsilon_0}$, so $\rho_v=\rho_0$.`,
   R`<b>Region $a\le r\le b$:</b> $r^2E_2=\dfrac{\rho_0}{3\epsilon_0}(2a^3-r^3)$. $\dfrac{d}{dr}=\dfrac{\rho_0}{3\epsilon_0}(-3r^2)=-\dfrac{\rho_0r^2}{\epsilon_0}$. Divide by $r^2$: $\rho_v=-\rho_0$.`,
   R`<b>Region $r\ge b$:</b> $r^2E_3=\dfrac{(2a^3-b^3)\rho_0}{3\epsilon_0}$ is a constant, so its derivative is 0 and $\rho_v=0$.`,
   R`<b>Boundaries.</b> At $r=a$: $E_1=\dfrac{a\rho_0}{3\epsilon_0}$ and $E_2=\dfrac{(2a^3-a^3)\rho_0}{3\epsilon_0a^2}=\dfrac{a\rho_0}{3\epsilon_0}$, equal, so no surface charge. At $r=b$, $E_2=E_3$ too. The only charge is the two volume layers.`,
   R`<b>(b) Total charge.</b> Gauss: $Q=\epsilon_0E_3\,(4\pi r^2)=\dfrac{4\pi}{3}(2a^3-b^3)\rho_0$.<br>Check by adding the layers: $+\rho_0\tfrac43\pi a^3$ for the core, $-\rho_0\tfrac43\pi(b^3-a^3)$ for the shell $=\tfrac{4\pi}{3}\rho_0(2a^3-b^3)$ ✓.`],
   R`(a) $\rho_v=\rho_0$ for $0\le r<a$; $\ \rho_v=-\rho_0$ for $a<r<b$; $\ \rho_v=0$ for $r>b$. (b) $Q=\dfrac{4\pi}{3}(2a^3-b^3)\rho_0$.`)},
 {pid:"a2:4", src:"HW2 Q5 · work", q:R`Find the work done in carrying a 2 μC charge from $(2,1,-1)$ to $(8,2,-1)$ in the field $\vec E=y\,\hat a_x+x\,\hat a_y$ along (a) the parabola $x=2y^2$, (b) the hyperbola $x=8/(7-3y)$, (c) the straight line $x=6y-4$.`,
  a:S(R`Work done in carrying a charge $Q$ against a field is $W=-Q\int\vec E\cdot d\vec l$. Here $\vec E\cdot d\vec l=y\,dx+x\,dy$. Check that each path hits both end points, then integrate (or notice a shortcut).`,[
   R`<b>End points.</b> Parabola: $y=1\to x=2$ ✓, $y=2\to x=8$ ✓. Hyperbola: $y=1\to8/4=2$ ✓, $y=2\to8/1=8$ ✓. Line: $y=1\to2$ ✓, $y=2\to8$ ✓. ($z=-1$ is constant, so $dz=0$.)`,
   R`<b>(a) Parabola.</b> $x=2y^2\Rightarrow dx=4y\,dy$. $\ \int(y\,dx+x\,dy)=\int_1^2(4y^2+2y^2)\,dy=\int_1^26y^2dy=2y^3\Big|_1^2=16-2=14$ V.`,
   R`<b>(c) Straight line.</b> $x=6y-4\Rightarrow dx=6\,dy$. $\ \int_1^2\big[y(6)+(6y-4)\big]dy=\int_1^2(12y-4)\,dy=\big[6y^2-4y\big]_1^2=(24-8)-(6-4)=14$ V.`,
   R`<b>(b) Hyperbola, and why they all agree.</b> Notice $y\,dx+x\,dy=d(xy)$, an exact differential (so $\vec E=\nabla(xy)$ is conservative, with $\nabla\times\vec E=0$). Then the integral depends only on the end points, $[xy]=8(2)-2(1)=14$ V, on <i>any</i> path, including the hyperbola.`,
   R`<b>Work.</b> $W=-Q\int\vec E\cdot d\vec l=-(2\times10^{-6})(14)=-28\times10^{-6}$ J.`],
   R`$W=\mathbf{-28\ \mu J}$ on all three paths. (The field itself does $+28\ \mu$J on the charge; the negative sign is the work done by an external agent carrying it along.)`,
   R`If your three answers differ, you have made an algebra slip: a conservative field must give the same work on every path between the same end points.`)},
 {pid:"a2:5", src:"HW2 Q6 · potential to field", q:R`The scalar field $V=2xy^2z^3$ is given. At $P(1,2,-1)$ find (a) the electric field $\vec E$ and (b) the charge density $\rho_v$.`,
  a:S(R`Two standard relations: $\vec E=-\nabla V$ and Poisson's equation $\nabla^2V=-\rho_v/\epsilon_0$.`,[
   R`<b>(a) Gradient.</b> $\dfrac{\partial V}{\partial x}=2y^2z^3,\ \dfrac{\partial V}{\partial y}=4xyz^3,\ \dfrac{\partial V}{\partial z}=6xy^2z^2$.`,
   R`At $P(1,2,-1)$: $z^3=-1$, $y^2=4$, $z^2=1$:<br>$\partial V/\partial x=2(4)(-1)=-8$, $\ \partial V/\partial y=4(1)(2)(-1)=-8$, $\ \partial V/\partial z=6(1)(4)(1)=24$.`,
   R`$\vec E=-\nabla V=-(-8,\,-8,\,24)=(8,\,8,\,-24)$ V/m.`,
   R`<b>(b) Laplacian.</b> $\dfrac{\partial^2V}{\partial x^2}=0$, $\ \dfrac{\partial^2V}{\partial y^2}=4xz^3$, $\ \dfrac{\partial^2V}{\partial z^2}=12xy^2z$. At $P$: $0+4(1)(-1)+12(1)(4)(-1)=-4-48=-52$.`,
   R`$\rho_v=-\epsilon_0\nabla^2V=-\epsilon_0(-52)=52\,\epsilon_0=52(8.854\times10^{-12})=4.60\times10^{-10}$ C/m³.`],
   R`(a) $\vec E=\mathbf{8\hat a_x+8\hat a_y-24\hat a_z}$ V/m. (b) $\rho_v=\mathbf{52\epsilon_0=4.60\times10^{-10}}$ C/m³.`,
   R`Mind the minus signs: $\vec E=-\nabla V$ and $\rho_v=-\epsilon_0\nabla^2V$.`)},
 {pid:"a2:6", src:"HW2 Q7 · potential of a disc", q:R`The circular disc of radius $a$ in the figure carries uniform surface charge density $\rho_s$. (a) Find the potential $V$ at $P(0,0,z)$ on the $z$-axis. (b) Use it to find $\vec E$ and evaluate it at $z=h$. (Hint: potential first, then the field.)`,
  a:S(R`Build the disc from thin rings. Every point of a ring is the same distance from $P$, so the ring's potential is just $\dfrac{dq}{4\pi\epsilon_0R}$ (a scalar, no direction to track). Integrate over rings, then take $-\partial/\partial z$.`,[
   R`<b>One ring.</b> Radius $r$, width $dr$: $dq=\rho_s(2\pi r\,dr)$. Distance to $P$: $R=\sqrt{r^2+z^2}$. $$dV=\frac{\rho_s2\pi r\,dr}{4\pi\epsilon_0\sqrt{r^2+z^2}}=\frac{\rho_s}{2\epsilon_0}\frac{r\,dr}{\sqrt{r^2+z^2}}.$$`,
   R`<b>Integrate</b> from $r=0$ to $a$. Since $\dfrac{d}{dr}\sqrt{r^2+z^2}=\dfrac{r}{\sqrt{r^2+z^2}}$: $$V=\frac{\rho_s}{2\epsilon_0}\Big[\sqrt{r^2+z^2}\Big]_0^a=\frac{\rho_s}{2\epsilon_0}\Big(\sqrt{a^2+z^2}-|z|\Big),$$ taking $V=0$ at infinity (check: for $z\to\infty$, $\sqrt{a^2+z^2}-z\approx a^2/2z\to0$ ✓).`,
   R`<b>(b) Field.</b> By symmetry $\vec E$ is along $\hat z$. For $z>0$: $E_z=-\dfrac{dV}{dz}=-\dfrac{\rho_s}{2\epsilon_0}\Big(\dfrac{z}{\sqrt{a^2+z^2}}-1\Big)=\dfrac{\rho_s}{2\epsilon_0}\Big(1-\dfrac{z}{\sqrt{a^2+z^2}}\Big).$`,
   R`<b>At $z=h$:</b> substitute. <b>Limits:</b> $h\to0$ gives $\dfrac{\rho_s}{2\epsilon_0}$ (infinite sheet); $h\gg a$ gives $\dfrac{\rho_s\pi a^2}{4\pi\epsilon_0h^2}$ (point charge $Q=\rho_s\pi a^2$).`],
   R`$V=\dfrac{\rho_s}{2\epsilon_0}\big(\sqrt{z^2+a^2}-|z|\big)$ and $\ \vec E(0,0,h)=\dfrac{\rho_s}{2\epsilon_0}\Big(1-\dfrac{h}{\sqrt{h^2+a^2}}\Big)\hat z$ (for $h>0$).`,
   R`Differentiate after finding $V$, as the hint says; it avoids a two-component vector integral.`)},
 {pid:"a2:7", src:"HW2 Q8 · potential differences", q:R`The plane $z=0$ carries $\rho_{s1}=0.2$ nC/m² and the plane $z=6$ m carries $\rho_{s2}=-0.2$ nC/m². Find $V_{AB}$, $V_{BC}$ and $V_{AC}$ for $A(0,0,6)$, $B(0,0,0)$ and $C(0,-2,2)$ m.`,
  a:S(R`Superpose the fields of the two infinite sheets (each $\dfrac{\rho_s}{2\epsilon_0}$, uniform), then use $V_{AB}=-\int_B^A\vec E\cdot d\vec l$ along any path (here along $z$).`,[
   R`<b>Each sheet.</b> A positive sheet's field points away from it; a negative sheet's field points toward it.`,
   R`<b>Between the sheets ($0<z<6$).</b> The $+$ sheet at $z=0$ pushes $+\hat z$ with $\dfrac{0.2\text{ nC/m}^2}{2\epsilon_0}$; the $-$ sheet at $z=6$ also pulls toward itself, $+\hat z$, with the same size. They add: $$E_z=\frac{\rho_s}{\epsilon_0}=\frac{0.2\times10^{-9}}{8.854\times10^{-12}}=22.6\ \text{V/m}.$$ Outside the sheets they cancel (each side sees one pushing and one pulling in opposite senses).`,
   R`<b>Potential differences.</b> $\vec E=E\hat z$ is uniform, so only the $z$-coordinates matter ($x,y$ displacements are perpendicular to $\vec E$).<br>$V_{AB}=-E(z_A-z_B)=-22.6(6-0)=-135.5$ V<br>$V_{BC}=-E(z_B-z_C)=-22.6(0-2)=+45.2$ V<br>$V_{AC}=-E(z_A-z_C)=-22.6(6-2)=-90.4$ V`,
   R`<b>Check:</b> $V_{AC}=V_{AB}+V_{BC}=-135.5+45.2=-90.3$ V ✓ (potential differences add around any path).`],
   R`$V_{AB}=\mathbf{-135.5}$ V, $\ V_{BC}=\mathbf{+45.2}$ V, $\ V_{AC}=\mathbf{-90.4}$ V.`,
   R`Potential falls <i>along</i> $\vec E$, so going up in $z$ (A is higher than B) means a lower potential: $V_{AB}<0$.`)},
]},

{id:"hw2o", title:"Homework 2 · optional practice (with solutions)", icon:"🧩", c:["#14b8a6","#22c55e"], note:"The supplied solutions, with the reasoning spelled out.", items:[
 {pid:"a2o:0", src:"HW2 Optional · Gauss Q1", q:R`A square plate in the $xy$-plane occupies $-3\le x\le3$ m, $-3\le y\le3$ m. Find the total charge if $\rho_s=4y^2\ \mu$C/m².`,
  a:S(R`Total charge on a surface with varying density is $Q=\iint\rho_s\,dS$.`,[
   R`The density depends only on $y$; $x$ just contributes a length. $dS=dx\,dy$.`,
   R`$$Q=\int_{-3}^{3}\!\int_{-3}^{3}4y^2\,dx\,dy=\Big(\int_{-3}^{3}dx\Big)\Big(4\int_{-3}^{3}y^2dy\Big)=6\cdot4\Big[\frac{y^3}{3}\Big]_{-3}^{3}=24\Big(\frac{27+27}{3}\Big)=24(18).$$`],
   R`$Q=\mathbf{432\ \mu C}$.`)},
 {pid:"a2o:1", src:"HW2 Optional · Gauss Q2", q:R`A thick spherical shell between $R=2$ cm and $R=3$ cm has $\rho_v=3R\times10^{-4}$ C/m³. Find the total charge in the shell.`,
  a:S(R`$Q=\int\rho_v\,dV$ with the spherical volume element $dV=R^2\sin\theta\,dR\,d\theta\,d\phi$.`,[
   R`The angles integrate to $4\pi$: $\int_0^{2\pi}d\phi\int_0^\pi\sin\theta\,d\theta=4\pi$.`,
   R`$$Q=4\pi\int_{0.02}^{0.03}(3R\times10^{-4})R^2\,dR=12\pi\times10^{-4}\Big[\frac{R^4}{4}\Big]_{0.02}^{0.03}=3\pi\times10^{-4}\,(0.03^4-0.02^4).$$`,
   R`$0.03^4=8.1\times10^{-7}$ and $0.02^4=1.6\times10^{-7}$, so $Q=3\pi\times10^{-4}(6.5\times10^{-7})=6.1\times10^{-10}$ C.`],
   R`$Q=\mathbf{0.61\ nC}$.`,
   R`Convert centimetres to metres before raising to the fourth power.`)},
 {pid:"a2o:2", src:"HW2 Optional · Gauss Q3", q:R`Three infinite lines of charge, parallel to the $z$-axis, sit at the corners of the kite shown: $\rho_l$ at the left and right corners and $-2\rho_l$ at the top. The two triangles are congruent. Show that the electric field at the origin is zero.`,
  a:S(R`Use the infinite-line field $E=\dfrac{\rho_l}{2\pi\epsilon_0r}$ (radial) for each line, then add the three vectors at the origin.`,[
   R`<b>Geometry.</b> Let the left and right lines be at distance $R_1$ from the origin, and the top line at distance $R_2$ up the $y$-axis. The right-angle markers in the figure say that the origin–left–top triangle has its right angle at the left corner, so the angle $\alpha$ between the line from the left corner to the origin and the $y$-axis satisfies $\cos\alpha=\dfrac{R_1}{R_2}$ (adjacent over hypotenuse).`,
   R`<b>Left and right lines.</b> Both are positive, so their fields at the origin point <i>away</i> from them, each with magnitude $\dfrac{\rho_l}{2\pi\epsilon_0R_1}$. By symmetry the $x$-components cancel. Each has a $y$-component of $-\dfrac{\rho_l}{2\pi\epsilon_0R_1}\cos\alpha$ (downward), so together $$-2\hat y\,\frac{\rho_l}{2\pi\epsilon_0R_1}\cdot\frac{R_1}{R_2}=-\hat y\,\frac{2\rho_l}{2\pi\epsilon_0R_2}.$$`,
   R`<b>Top line.</b> It is negative, so its field at the origin points <i>toward</i> it, i.e. $+\hat y$, with magnitude $\dfrac{2\rho_l}{2\pi\epsilon_0R_2}$.`,
   R`<b>Sum:</b> $\vec E=-\hat y\dfrac{2\rho_l}{2\pi\epsilon_0R_2}+\hat y\dfrac{2\rho_l}{2\pi\epsilon_0R_2}=0$.`],
   R`$\vec E=\mathbf0$ at the origin. ✓`)},
 {pid:"a2o:3", src:"HW2 Optional · Gauss Q4", q:R`Charge $Q_1$ is spread uniformly on a thin spherical shell of radius $a$ and $Q_2$ on a second shell of radius $b>a$. Apply Gauss's law to find $E$ for $R<a$, $a<R<b$ and $R>b$.`,
  a:S(R`Spherical symmetry: a Gaussian sphere of radius $R$ gives $E\,4\pi R^2=Q_{enc}/\epsilon_0$, so $E=\dfrac{Q_{enc}}{4\pi\epsilon_0R^2}$ directed radially.`,[
   R`$R<a$: the sphere lies inside both shells, so $Q_{enc}=0$ and $E=0$.`,
   R`$a<R<b$: it encloses only the inner shell, $Q_{enc}=Q_1$, so $E=\dfrac{Q_1}{4\pi\epsilon_0R^2}$.`,
   R`$R>b$: it encloses both, $Q_{enc}=Q_1+Q_2$, so $E=\dfrac{Q_1+Q_2}{4\pi\epsilon_0R^2}$.`],
   R`$E=0\ (R<a)$; $\ \dfrac{Q_1}{4\pi\epsilon_0R^2}\hat R\ (a<R<b)$; $\ \dfrac{Q_1+Q_2}{4\pi\epsilon_0R^2}\hat R\ (R>b)$.`)},
 {pid:"a2o:4", src:"HW2 Optional · Gauss Q5", q:R`An infinitely long cylindrical shell between $r=1$ m and $r=3$ m has uniform charge density $\rho_{v0}$. Apply Gauss's law to find $E$ in all regions.`,
  a:S(R`Coaxial Gaussian cylinder of radius $r$, length $L$: $E\,(2\pi rL)=Q_{enc}/\epsilon_0$. The charge is distributed through a volume, so $Q_{enc}=\rho_{v0}\times$ (enclosed volume of the shell).`,[
   R`$r<1$: nothing enclosed, so $E=0$.`,
   R`$1\le r\le3$: the enclosed volume is the part of the shell inside radius $r$: $\pi L(r^2-1^2)$. So $E\,2\pi rL=\dfrac{\rho_{v0}\pi L(r^2-1)}{\epsilon_0}\Rightarrow E=\dfrac{\rho_{v0}(r^2-1)}{2\epsilon_0r}$.`,
   R`$r\ge3$: the whole shell is enclosed: $\pi L(3^2-1^2)=8\pi L$. So $E\,2\pi rL=\dfrac{8\pi L\rho_{v0}}{\epsilon_0}\Rightarrow E=\dfrac{4\rho_{v0}}{\epsilon_0r}$.`,
   R`<b>Check.</b> At $r=3$ the middle formula gives $\dfrac{\rho_{v0}(9-1)}{6\epsilon_0}=\dfrac{4\rho_{v0}}{3\epsilon_0}$, the same as $\dfrac{4\rho_{v0}}{\epsilon_0\cdot3}$ ✓ (continuous).`],
   R`$E=0\ (r<1)$; $\ \dfrac{\rho_{v0}(r^2-1)}{2\epsilon_0r}\hat r\ (1\le r\le3)$; $\ \dfrac{4\rho_{v0}}{\epsilon_0r}\hat r\ (r\ge3)$.`)},
 {pid:"a2p:0", src:"HW2 Optional · Potential Q1", q:R`A square in the $xy$-plane has charge $Q$ at the corners $(a/2,\,a/2)$ and $(a/2,\,-a/2)$ and $-Q$ at the corners $(-a/2,\,\pm a/2)$. (a) Find the potential at a point $P(x,0)$ on the $x$-axis. (b) Evaluate $V$ at $x=a/2$.`,
  a:S(R`Potential is a scalar: add $\dfrac{Q_i}{4\pi\epsilon_0R_i}$ for the four charges, using the symmetry about the $x$-axis to pair them up.`,[
   R`<b>Distances.</b> The two $+Q$ at $x=a/2$ are both at $R_1=\sqrt{(x-\frac a2)^2+(\frac a2)^2}$ from $P$ (one above, one below the axis). The two $-Q$ at $x=-a/2$ are both at $R_3=\sqrt{(x+\frac a2)^2+(\frac a2)^2}$.`,
   R`<b>(a)</b> $V=\dfrac{1}{4\pi\epsilon_0}\Big[\dfrac{2Q}{R_1}-\dfrac{2Q}{R_3}\Big]=\dfrac{Q}{2\pi\epsilon_0}\Big(\dfrac1{R_1}-\dfrac1{R_3}\Big)$.`,
   R`<b>(b)</b> At $x=a/2$: $R_1=\sqrt{0+(\frac a2)^2}=\dfrac a2$ and $R_3=\sqrt{a^2+\frac{a^2}{4}}=\dfrac{a\sqrt5}{2}$.<br>$V=\dfrac{Q}{2\pi\epsilon_0}\Big(\dfrac2a-\dfrac{2}{\sqrt5\,a}\Big)=\dfrac{Q}{\pi\epsilon_0a}\Big(1-\dfrac1{\sqrt5}\Big)=\dfrac{0.553\,Q}{\pi\epsilon_0a}$.`],
   R`(a) $V=\dfrac{Q}{2\pi\epsilon_0}\Big(\dfrac1{R_1}-\dfrac1{R_3}\Big)$. (b) $V(a/2)=\dfrac{0.55\,Q}{\pi\epsilon_0a}$.`,
   R`The potential at points on the line $x=0$ (the perpendicular bisector) is zero: there $R_1=R_3$.`)},
 {pid:"a2p:1", src:"HW2 Optional · Potential Q2", q:R`Find the potential at a distance $b$ from the origin in the $xy$-plane due to a line charge $\rho_l$ of length $l$ along the $z$-axis, from $z=-l/2$ to $z=l/2$.`,
  a:S(R`Break the line into elements $dq=\rho_l\,dz$, each a distance $R'=\sqrt{z^2+b^2}$ from the field point, and add their scalar potentials.`,[
   R`$V(b)=\dfrac{1}{4\pi\epsilon}\displaystyle\int\frac{\rho_l\,dz}{R'}=\dfrac{\rho_l}{4\pi\epsilon}\int_{-l/2}^{l/2}\frac{dz}{\sqrt{z^2+b^2}}$.`,
   R`The standard integral is $\int\dfrac{dz}{\sqrt{z^2+b^2}}=\ln\big(z+\sqrt{z^2+b^2}\big)$. Evaluate between the limits: $$\ln\Big(\tfrac l2+\sqrt{\tfrac{l^2}{4}+b^2}\Big)-\ln\Big(-\tfrac l2+\sqrt{\tfrac{l^2}4+b^2}\Big)=\ln\frac{l+\sqrt{l^2+4b^2}}{-l+\sqrt{l^2+4b^2}}.$$`,
   R`<b>Check the limit $b\gg l$:</b> the line looks like a point charge $\rho_ll$. Then $\sqrt{l^2+4b^2}\approx2b$, so the log is $\ln\dfrac{2b+l}{2b-l}\approx\ln\Big(1+\dfrac lb\Big)\approx\dfrac lb$, giving $V\approx\dfrac{\rho_ll}{4\pi\epsilon b}$ ✓.`],
   R`$$V(b)=\frac{\rho_l}{4\pi\epsilon}\ln\!\left(\frac{l+\sqrt{l^2+4b^2}}{-l+\sqrt{l^2+4b^2}}\right)$$`)},
 {pid:"a2p:2", src:"HW2 Optional · Potential Q3", q:R`A spherical capacitor (a cell membrane) has shells of radii $a=90$ nm and $b=100$ nm carrying $-Q$ (inner) and $+Q$ (outer), with free space between. (a) Find $C$. (b) If the potential difference is 70 mV, find the stored energy.`,
  a:S(R`Gauss's law gives the field between the shells; integrate it for the voltage; then $C=Q/V$ and $W=\tfrac12CV^2$.`,[
   R`<b>Field.</b> Between the shells, a Gaussian sphere encloses only the inner charge: $|E|=\dfrac{Q}{4\pi\epsilon_0r^2}$, radial.`,
   R`<b>Voltage.</b> $|V|=\int_a^b|E|\,dr=\dfrac{Q}{4\pi\epsilon_0}\Big(\dfrac1a-\dfrac1b\Big)=\dfrac{Q}{4\pi\epsilon_0}\dfrac{b-a}{ab}$.`,
   R`<b>(a) Capacitance.</b> $C=\dfrac{Q}{|V|}=\dfrac{4\pi\epsilon_0ab}{b-a}=\dfrac{4\pi(8.854\times10^{-12})(9\times10^{-8})(10^{-7})}{10^{-8}}=1.0\times10^{-16}$ F.`,
   R`<b>(b) Energy.</b> $W=\tfrac12CV^2=\tfrac12(1.0\times10^{-16})(0.070)^2=2.45\times10^{-19}$ J.`],
   R`(a) $C\approx\mathbf{1.0\times10^{-16}}$ F. (b) $W\approx\mathbf{2.45\times10^{-19}}$ J.`,
   R`The gap is only $10$ nm, so $C$ is tiny but it equals the parallel-plate value $\epsilon_0A/d$ with $A\approx4\pi(95\text{ nm})^2$: a good check.`)},
]},

{id:"hw3", title:"Homework 3 · conductors, current, dielectrics, capacitors", icon:"3️⃣", c:["#f59e0b","#f97316"], note:"The seven main questions with detailed solutions (due 27 Oct). Optional practice follows.", items:[
 {pid:"a3:0", src:"HW3 Q1 · image method", q:R`Two point charges, each $-100\pi\ \mu$C, are at $(2,-1,0)$ and $(2,1,0)$ m. The plane $x=0$ is an infinite grounded conductor; the region $x>0$ is free space. (a) Find the surface charge density at the origin. (b) Find $\rho_s$ at $P(0,h,0)$. (Hint: images.)`,
  a:S(R`A grounded conducting plane acts like a mirror: replace it by <i>image charges</i> of opposite sign at the mirror positions. Then, on the plane, $\vec E$ is normal (along $x$) and $\rho_s=\epsilon_0E_x$.`,[
   R`<b>Images.</b> Mirror in $x=0$: $(2,\mp1,0)\to(-2,\mp1,0)$ with the opposite charge: two charges $+q$ at $(-2,\pm1,0)$, where $q=100\pi\ \mu$C. Now four charges: two real $-q$ and two image $+q$.`,
   R`<b>Field at $P(0,h,0)$ from one real charge</b> at $(2,y_s,0)$: the vector from source to $P$ is $\vec R=(-2,\,h-y_s,\,0)$, $R=\sqrt{4+(h-y_s)^2}$. Field $=\dfrac{k(-q)\vec R}{R^3}$, whose $x$-component is $\dfrac{k(-q)(-2)}{R^3}=+\dfrac{2kq}{R^3}$ (toward the plane, as expected for a negative charge).`,
   R`<b>From the matching image</b> $+q$ at $(-2,y_s,0)$: $\vec R=(2,\,h-y_s,\,0)$, $x$-component $\dfrac{kq(2)}{R^3}=+\dfrac{2kq}{R^3}$: the same. The $y$-components of real and image cancel. So each real–image pair gives $E_x=\dfrac{4kq}{R^3}$.`,
   R`<b>Sum over $y_s=\pm1$:</b> $E_x=4kq\Big[\dfrac1{(4+(h-1)^2)^{3/2}}+\dfrac1{(4+(h+1)^2)^{3/2}}\Big]$. Then $\rho_s=\epsilon_0E_x$, and $\epsilon_0k=\dfrac1{4\pi}$: $$\rho_s=\frac{q}{\pi}\Big[\dfrac1{(h^2-2h+5)^{3/2}}+\dfrac1{(h^2+2h+5)^{3/2}}\Big].$$ With $q/\pi=100\ \mu$C this is the formula below.`,
   R`<b>(a) At the origin</b> $h=0$: both terms equal $5^{-3/2}=0.0894$, so $\rho_s=100\ \mu\text{C}\times2(0.0894)=17.9\ \mu\text{C/m}^2$.`],
   R`(a) $\rho_s(0)=\dfrac{200}{5^{3/2}}\ \mu\text{C/m}^2=\mathbf{17.9\ \mu C/m^2}$. (b) $\rho_s(h)=100\Big[(h^2-2h+5)^{-3/2}+(h^2+2h+5)^{-3/2}\Big]\ \mu\text{C/m}^2$.`,
   R`The induced charge is <i>positive</i> because the real charges are negative: $\rho_s=\epsilon_0E_n$ with $E_n$ pointing along $+x$ (into the region $x>0$, away from the plane), as $\vec E$ points from the plane toward the real charges.`)},
 {pid:"a3:1", src:"HW3 Q2 · current density", q:R`The current density in a cylindrical conductor of radius $a=2$ mm is $\vec J=J_0\dfrac{\rho}{a}\hat z$ with $J_0=10^5$ A/m², where $\rho$ is the distance from the axis. (a) Find the total current $I$. (b) Find the average current density.`,
  a:S(R`Current is the flux of $\vec J$ through the cross-section: $I=\iint\vec J\cdot d\vec S$. Because $J$ depends on $\rho$, integrate over thin rings.`,[
   R`<b>(a)</b> A ring of radius $\rho$ and width $d\rho$ has area $dS=2\pi\rho\,d\rho$, and $\vec J\parallel d\vec S$ (both along $z$), so $$I=\int_0^aJ_0\frac{\rho}{a}\,2\pi\rho\,d\rho=\frac{2\pi J_0}{a}\int_0^a\rho^2d\rho=\frac{2\pi J_0}{a}\cdot\frac{a^3}{3}=\frac{2\pi}{3}J_0a^2.$$`,
   R`<b>Numbers:</b> $I=\dfrac{2\pi}{3}(10^5)(2\times10^{-3})^2=\dfrac{2\pi}{3}(0.4)=0.838$ A.`,
   R`<b>(b) Average.</b> $J_{avg}=\dfrac{I}{\pi a^2}=\dfrac{\frac{2\pi}{3}J_0a^2}{\pi a^2}=\dfrac23J_0=6.67\times10^4$ A/m².`],
   R`(a) $I=\mathbf{0.838}$ A. (b) $J_{avg}=\mathbf{6.67\times10^4}$ A/m² (two-thirds of $J_0$).`,
   R`$J_{avg}\ne J_0$ because $J_0$ is the value only at the surface $\rho=a$; the current density is smaller toward the axis.`)},
 {pid:"a3:2", src:"HW3 Q3 · Ohm's law", q:R`A current flows through a 100 m long wire of uniform cross-section with current density $3\times10^5$ A/m². Find the voltage drop along the wire if $\sigma=2\times10^7$ S/m.`,
  a:S(R`Use $\vec J=\sigma\vec E$ for the field inside the metal, then $V=El$ for a uniform field along the wire.`,[
   R`$E=\dfrac{J}{\sigma}=\dfrac{3\times10^5\ \text{A/m}^2}{2\times10^7\ \text{S/m}}=0.015$ V/m.`,
   R`$V=El=(0.015)(100)=1.5$ V.`,
   R`<b>Check by the resistance route.</b> $I=JA$ and $R=\dfrac{l}{\sigma A}$, so $V=IR=JA\dfrac{l}{\sigma A}=\dfrac{Jl}{\sigma}$, the same.`],
   R`$V=\mathbf{1.5}$ V.`,
   R`You don't need the wire's area: it cancels between $I=JA$ and $R=l/\sigma A$.`)},
 {pid:"a3:3", src:"HW3 Q4 · boundary conditions", q:R`Three planar dielectric slabs of equal thickness have $\epsilon_{r1}=3$, $\epsilon_{r2}=5$, $\epsilon_{r3}=7$ and are laterally infinite with no free interface charge. $\vec E_0$ in the air above makes a 45° angle with the $z$-axis. Find the angle of $\vec E$ with the $z$-axis in each dielectric layer and in the lower air region.`,
  a:S(R`At a charge-free interface two things are continuous: the <b>tangential $E$</b> and the <b>normal $D$</b>. Together they give a refraction law for the field direction.`,[
   R`<b>Derive the law.</b> Let $\theta_1,\theta_2$ be the angles from the normal ($z$-axis). Tangential: $E_1\sin\theta_1=E_2\sin\theta_2$. Normal $D$: $\epsilon_1E_1\cos\theta_1=\epsilon_2E_2\cos\theta_2$. Divide the first by the second: $$\frac{\tan\theta_1}{\epsilon_1}=\frac{\tan\theta_2}{\epsilon_2}\ \Rightarrow\ \tan\theta_2=\frac{\epsilon_2}{\epsilon_1}\tan\theta_1.$$`,
   R`<b>Air → layer 1</b> ($\epsilon_0\to3\epsilon_0$): $\tan\theta_1=3\tan45°=3\Rightarrow\theta_1=71.6°$.`,
   R`<b>Layer 1 → 2:</b> $\tan\theta_2=\dfrac53(3)=5\Rightarrow\theta_2=78.7°$. <b>Layer 2 → 3:</b> $\tan\theta_3=\dfrac75(5)=7\Rightarrow\theta_3=81.9°$.`,
   R`<b>Layer 3 → air:</b> $\tan\theta=\dfrac{\epsilon_0}{7\epsilon_0}(7)=1\Rightarrow\theta=45°$.`],
   R`Layers: $\mathbf{71.6°}$, $\mathbf{78.7°}$, $\mathbf{81.9°}$; lower air: $\mathbf{45°}$ (the same as the incident angle).`,
   R`The angle is measured from the <i>normal</i> ($z$-axis), as the question asks. The field bends <i>toward the interface</i> (away from the normal) in higher-$\epsilon$ media.`)},
 {pid:"a3:4", src:"HW3 Q5 · boundary conditions", q:R`Region 1 ($z<0$) is free space and region 2 ($z>0$) is a perfect dielectric with $\epsilon_{r2}=4$. The interface carries no free charge. If $\vec E_1=4\hat x+3\hat z$ V/m, find (a) $\vec E_2$ and $\vec D_2$; (b) the angles $\theta_1,\theta_2$ that $\vec E_1,\vec E_2$ make with the $z$-axis.`,
  a:S(R`The interface is the plane $z=0$, so the normal is $\hat z$ and the tangential directions are $x$ and $y$. Apply the boundary conditions component by component.`,[
   R`<b>Tangential $E$ is continuous:</b> $E_{2x}=E_{1x}=4$ (and $E_{2y}=0$).`,
   R`<b>Normal $D$ is continuous</b> (no free charge): $D_{2z}=D_{1z}$, i.e. $\epsilon_0\epsilon_{r2}E_{2z}=\epsilon_0E_{1z}\Rightarrow4E_{2z}=3\Rightarrow E_{2z}=0.75$.`,
   R`<b>$\vec E_2=4\hat x+0.75\hat z$ V/m.</b> Then $\vec D_2=\epsilon_0\epsilon_{r2}\vec E_2=4\epsilon_0(4\hat x+0.75\hat z)=\epsilon_0(16\hat x+3\hat z)=1.42\times10^{-10}\hat x+2.66\times10^{-11}\hat z$ C/m².`,
   R`<b>(b) Angles from the $z$-axis:</b> $\tan\theta_1=\dfrac{E_{1x}}{E_{1z}}=\dfrac43\Rightarrow\theta_1=53.1°$. $\ \tan\theta_2=\dfrac{4}{0.75}=5.33\Rightarrow\theta_2=79.4°$.<br>Check: $\dfrac{\tan\theta_2}{\tan\theta_1}=\dfrac{5.33}{1.33}=4=\dfrac{\epsilon_{r2}}{\epsilon_{r1}}$ ✓.`],
   R`(a) $\vec E_2=\mathbf{4\hat x+0.75\hat z}$ V/m, $\vec D_2=\mathbf{\epsilon_0(16\hat x+3\hat z)}$ C/m². (b) $\theta_1=\mathbf{53.1°}$, $\theta_2=\mathbf{79.4°}$.`)},
 {pid:"a3:5", src:"HW3 Q6 · coaxial capacitor", q:R`Two coaxial conducting cylinders of radii $a=2$ cm and $b=4$ cm have length $L=1$ m. The region between them has a dielectric layer ($\epsilon_r=4$) from $\rho=c$ to $\rho=d$; the rest is air. Neglect end effects. Find the capacitance if (a) $c=2$ cm, $d=3$ cm; (b) $d=4$ cm and the dielectric has the same volume as in (a).`,
  a:S(R`Put charge $Q$ on the inner cylinder. $D$ is radial and the same function of $\rho$ in every layer, so $E=\dfrac{Q}{2\pi\epsilon L\rho}$ in each layer. Add the layer voltages, then $C=Q/V$. Concentric layers behave as capacitors in <i>series</i>.`,[
   R`<b>Gauss.</b> $D\,(2\pi\rho L)=Q\Rightarrow D=\dfrac{Q}{2\pi\rho L}$. In a layer of permittivity $\epsilon$: $E=\dfrac{D}{\epsilon}$.`,
   R`<b>Voltage across a layer</b> from $\rho_1$ to $\rho_2$: $\displaystyle\int E\,d\rho=\frac{Q}{2\pi\epsilon L}\ln\frac{\rho_2}{\rho_1}$. Add the air parts (with $\epsilon_0$) and the dielectric part (with $4\epsilon_0$): $$\frac1C=\frac{V}{Q}=\frac{1}{2\pi\epsilon_0L}\Big[\ln\frac ca+\frac14\ln\frac dc+\ln\frac bd\Big].$$`,
   R`<b>(a)</b> $c=a$, so the first term vanishes. $\ \tfrac14\ln\dfrac32+\ln\dfrac43=0.1014+0.2877=0.3890$. $\ C=\dfrac{2\pi\epsilon_0(1)}{0.3890}=\dfrac{5.563\times10^{-11}}{0.3890}=143$ pF.`,
   R`<b>(b) Same dielectric volume.</b> The dielectric volume per length is $\pi(d^2-c^2)$. In (a) it is $\pi(3^2-2^2)=5\pi$ cm². With $d=4$ cm: $16-c^2=5\Rightarrow c=\sqrt{11}=3.317$ cm.`,
   R`$\ln\dfrac{c}{a}=\ln\dfrac{3.317}{2}=0.5062$; $\ \tfrac14\ln\dfrac{4}{3.317}=\tfrac14(0.1876)=0.0469$; the last term $\ln(b/d)=0$. Sum $=0.5531$, so $C=\dfrac{5.563\times10^{-11}}{0.5531}=101$ pF.`],
   R`(a) $C=\mathbf{143}$ pF. (b) $C=\mathbf{101}$ pF.`,
   R`Same dielectric volume gives a <i>smaller</i> $C$ in (b): the dielectric is at larger radius, where $E$ is weaker, so it helps less.`)},
 {pid:"a3:6", src:"HW3 Q7 · two-layer capacitor", q:R`A parallel-plate capacitor has $A=50$ cm² and $d=4$ mm. The gap holds two layers of equal thickness (2 mm): $\epsilon_{r1}=2$ next to the lower plate (0 V) and $\epsilon_{r2}=6$ next to the upper plate (100 V). There is no free charge on the interface; take $+z$ upward and neglect fringing. (a) Find $C$. (b) Find $\vec E$ in each layer. (c) Find the stored energy.`,
  a:S(R`Layers parallel to the plates share the same $D$ (normal $D$ is continuous), so they behave as capacitors in <b>series</b>. Find $C$, then $Q=CV$, then $D=Q/A$ and $E_i=D/\epsilon_i$.`,[
   R`<b>(a) Capacitance.</b> $A=50\text{ cm}^2=5\times10^{-3}$ m². Each layer is 2 mm thick: $C_1=\dfrac{\epsilon_{r1}\epsilon_0A}{d_1}=\dfrac{2(8.854\times10^{-12})(5\times10^{-3})}{2\times10^{-3}}=44.3$ pF and $C_2=\dfrac{6\epsilon_0A}{d_2}=132.8$ pF.<br>Series: $C=\dfrac{C_1C_2}{C_1+C_2}=\dfrac{(44.3)(132.8)}{177.1}=33.2$ pF.`,
   R`<b>Charge and $D$.</b> $Q=CV=(33.2\times10^{-12})(100)=3.32$ nC, so $D=\dfrac QA=\dfrac{3.32\times10^{-9}}{5\times10^{-3}}=6.64\times10^{-7}$ C/m² in both layers.`,
   R`<b>(b) Fields.</b> $E_1=\dfrac{D}{\epsilon_{r1}\epsilon_0}=\dfrac{6.64\times10^{-7}}{2(8.854\times10^{-12})}=37.5$ kV/m and $E_2=\dfrac{D}{6\epsilon_0}=12.5$ kV/m. The upper plate is at the higher potential, so $\vec E$ points downward: $\vec E_1=-37.5\hat z$, $\vec E_2=-12.5\hat z$ kV/m.<br>Check: $37.5(2\text{ mm})+12.5(2\text{ mm})=75+25=100$ V ✓.`,
   R`<b>(c) Energy.</b> $W=\tfrac12CV^2=\tfrac12(33.2\times10^{-12})(100)^2=1.66\times10^{-7}$ J.`],
   R`(a) $C=\mathbf{33.2}$ pF. (b) $\vec E_1=\mathbf{-37.5\,\hat z}$ kV/m, $\vec E_2=\mathbf{-12.5\,\hat z}$ kV/m. (c) $W=\mathbf{166\ nJ}$.`,
   R`The field is <i>larger</i> in the lower-$\epsilon$ layer (same $D$, smaller $\epsilon$), and the larger share of the 100 V falls across it.`)},
]},

{id:"hw3o", title:"Homework 3 · optional practice (with solutions)", icon:"🧪", c:["#ec4899","#8b5cf6"], note:"The supplied solutions, with the reasoning spelled out.", items:[
 {pid:"a3o:0", src:"HW3 Optional Q1", q:R`A parallel-plate capacitor has circular plates of radius $a$; the bottom plate is on the $xy$-plane (grounded) and the top plate at $z=d$ is at $V_0$. A dielectric with $\epsilon(\rho)=\epsilon_0(1+\rho^2/a^2)$ fills the gap. Assuming no free volume charge and neglecting fringing, find (a) $V(z)$; (b) $\vec E$; (c) the charge $Q$ on the top plate; (d) $C$.`,
  a:S(R`With no free charge, $\nabla\cdot\vec D=0$, i.e. $\nabla\cdot(\epsilon\nabla V)=0$. Neglecting fringing, $V$ depends only on $z$, so the $\rho$-dependence of $\epsilon$ drops out of the equation.`,[
   R`<b>(a)</b> If $V=V(z)$ then $\nabla V=\dfrac{dV}{dz}\hat z$ and $\nabla\cdot(\epsilon\nabla V)=\epsilon\dfrac{d^2V}{dz^2}$ (since $\epsilon$ does not depend on $z$). So $\dfrac{d^2V}{dz^2}=0$, giving $V=Az+B$. Boundary conditions $V(0)=0$, $V(d)=V_0$: $$V(z)=\frac{V_0\,z}{d}.$$`,
   R`<b>(b)</b> $\vec E=-\nabla V=-\dfrac{V_0}{d}\hat z$, uniform, independent of $\rho$.`,
   R`<b>(c)</b> $\vec D=\epsilon\vec E=-\epsilon_0\Big(1+\dfrac{\rho^2}{a^2}\Big)\dfrac{V_0}{d}\hat z$. On the top plate the outward normal into the plate is $-\hat z$, so $\rho_s=\vec D\cdot(-\hat z)=\dfrac{\epsilon_0V_0}{d}\Big(1+\dfrac{\rho^2}{a^2}\Big)$. $$Q=\int_0^a\rho_s\,2\pi\rho\,d\rho=\frac{2\pi\epsilon_0V_0}{d}\Big[\frac{a^2}{2}+\frac{a^4}{4a^2}\Big]=\frac{2\pi\epsilon_0V_0}{d}\cdot\frac{3a^2}{4}=\frac{3\pi\epsilon_0a^2V_0}{2d}.$$`,
   R`<b>(d)</b> $C=\dfrac{Q}{V_0}=\dfrac{3\pi\epsilon_0a^2}{2d}$, which is $1.5\times$ the vacuum value $\dfrac{\pi\epsilon_0a^2}{d}$ (the average $\epsilon_r$ over the disc is $1+\tfrac12=1.5$).`],
   R`(a) $V=V_0z/d$. (b) $\vec E=-\dfrac{V_0}{d}\hat z$. (c) $Q=\dfrac{3\pi\epsilon_0a^2V_0}{2d}$. (d) $C=\dfrac{3\pi\epsilon_0a^2}{2d}$.`)},
 {pid:"a3o:1", src:"HW3 Optional Q2", q:R`A spherical capacitor has an inner sphere of radius $a=1$ mm and an outer shell of inner radius $c=2.5$ mm. Two dielectric layers fill the gap: $\epsilon_{r1}=4$ for $a<r<b$ and $\epsilon_{r2}=2$ for $b<r<c$, with $b=2$ mm. There is no free charge on the interface. $V=50$ V is applied (inner $+$). (a) Find $E$ in each layer in terms of $Q$. (b) Find $C$. (c) Find the stored energy.`,
  a:S(R`Gauss's law for $\vec D$ gives the same $D$ in both layers (spherical symmetry, no free charge on the interface). Divide by each $\epsilon$ to get $E$, integrate for $V$, and use $C=Q/V$.`,[
   R`<b>(a)</b> $D\,(4\pi r^2)=Q\Rightarrow D=\dfrac{Q}{4\pi r^2}\hat r$ for $a<r<c$. Then $E_1=\dfrac{D}{\epsilon_0\epsilon_{r1}}=\dfrac{Q}{4\pi\epsilon_0\epsilon_{r1}r^2}$ on $a<r<b$ and $E_2=\dfrac{Q}{4\pi\epsilon_0\epsilon_{r2}r^2}$ on $b<r<c$.`,
   R`<b>(b) Voltage.</b> $V=\int_a^bE_1dr+\int_b^cE_2dr=\dfrac{Q}{4\pi\epsilon_0}\Big[\dfrac1{\epsilon_{r1}}\Big(\dfrac1a-\dfrac1b\Big)+\dfrac1{\epsilon_{r2}}\Big(\dfrac1b-\dfrac1c\Big)\Big]$.`,
   R`Use $\dfrac1a=1000$, $\dfrac1b=500$, $\dfrac1c=400$ m⁻¹: the bracket is $\dfrac{500}{4}+\dfrac{100}{2}=125+50=175$ m⁻¹.`,
   R`$C=\dfrac QV=\dfrac{4\pi\epsilon_0}{175}=\dfrac{1.113\times10^{-10}}{175}=6.36\times10^{-13}$ F $=0.636$ pF.`,
   R`<b>(c) Energy.</b> $W=\tfrac12CV^2=\tfrac12(6.36\times10^{-13})(50)^2=7.95\times10^{-10}$ J $=0.795$ nJ.`],
   R`(a) $E_{1,2}=\dfrac{Q}{4\pi\epsilon_0\epsilon_{r1,2}\,r^2}$ in the two layers. (b) $C=0.636$ pF. (c) $W=0.795$ nJ.`)},
 {pid:"a3o:2", src:"HW3 Optional Q3", q:R`Two plates of area $A$ at $z=0$ (0 V) and $z=d$ ($V_0>0$) enclose a material with conductivity $\sigma(z)=\sigma_0e^{-z/d}$. Assume steady 1-D conduction and neglect edge effects. Find (a) the resistance, (b) the magnitude and direction of the total current, (c) $\vec E(z)$.`,
  a:S(R`In steady 1-D conduction the same current $I$ crosses every cross-section, so $J=I/A$ is constant even though $\sigma$ changes. A thin slice $dz$ has resistance $\dfrac{dz}{\sigma(z)A}$, and the slices add in series.`,[
   R`<b>(a) Resistance.</b> $R=\displaystyle\int_0^d\frac{dz}{\sigma(z)A}=\frac{1}{\sigma_0A}\int_0^de^{z/d}dz=\frac{1}{\sigma_0A}\Big[d\,e^{z/d}\Big]_0^d=\frac{d(e-1)}{\sigma_0A}$.`,
   R`<b>(b) Current.</b> $I=\dfrac{V_0}{R}=\dfrac{\sigma_0AV_0}{d(e-1)}$. The plate at $z=d$ is at the higher potential and conventional current flows from high to low potential, so it flows from $z=d$ to $z=0$, along $-\hat z$: $\vec J=-\dfrac IA\hat z$.`,
   R`<b>(c) Field.</b> $\vec E=\dfrac{\vec J}{\sigma(z)}=-\dfrac{I}{A\sigma_0e^{-z/d}}\hat z=-\dfrac{V_0\,e^{z/d}}{d(e-1)}\hat z$. The field is stronger where $\sigma$ is smaller (large $z$).`,
   R`<b>Check.</b> $V(z)=\dfrac{V_0(e^{z/d}-1)}{e-1}$ gives $V(0)=0$, $V(d)=V_0$, and $-dV/dz$ reproduces $\vec E$ ✓.`],
   R`(a) $R=\dfrac{d(e-1)}{\sigma_0A}$. (b) $I=\dfrac{\sigma_0AV_0}{d(e-1)}$ along $-\hat z$. (c) $\vec E=-\dfrac{V_0e^{z/d}}{d(e-1)}\hat z$.`)},
 {pid:"a3o:3", src:"HW3 Optional Q4", q:R`A conducting sphere of radius $a=5$ cm sits in free space. If $\vec E=150\,\hat r$ V/m just outside its surface, what is its total charge?`,
  a:S(R`At the surface of a conductor the field is normal and $E_n=\rho_s/\epsilon_0$.`,[
   R`$\rho_s=\epsilon_0E_n=(8.854\times10^{-12})(150)=1.33\times10^{-9}$ C/m².`,
   R`Uniform over the sphere: $Q=\rho_s\cdot4\pi a^2=(1.33\times10^{-9})\,4\pi(0.05)^2=4.17\times10^{-11}$ C.`,
   R`<b>Cross-check with Gauss:</b> $Q=\epsilon_0E(4\pi a^2)$, the same.`],
   R`$Q=\mathbf{41.7\ pC}$ (positive, since $\vec E$ points outward).`)},
 {pid:"a3o:4", src:"HW3 Optional Q5", q:R`A conducting sphere of radius $a=1$ cm carrying a total charge $Q=20$ nC is covered by a concentric dielectric shell ($\epsilon_r=3$) from $r=a$ to $r=b=3$ cm; free space beyond. (a) Find $\vec D$ everywhere. (b) Find $\vec E$ in the three regions. (c) Find the bound surface charge densities at $r=a$ and $r=b$ and show the shell's total bound charge is zero. (d) Find the potential of the conducting sphere with respect to infinity.`,
  a:S(R`$\vec D$ depends only on free charge, so Gauss's law gives it directly. Then $\vec E=\vec D/\epsilon$ region by region, $\vec P=\vec D-\epsilon_0\vec E$ for the polarisation, and $V=-\int\vec E\cdot d\vec l$ from infinity inward.`,[
   R`<b>(a)</b> $\vec D=0$ for $r<a$ (inside the conductor). For $r>a$ the free charge $Q$ is enclosed: $\vec D=\dfrac{Q}{4\pi r^2}\hat r=\dfrac{1.59\times10^{-9}}{r^2}\hat r$ C/m², the same in the dielectric and in free space.`,
   R`<b>(b)</b> $r<a$: $E=0$. $\ a<r<b$: $E=\dfrac{D}{\epsilon_0\epsilon_r}=\dfrac{Q}{4\pi\epsilon_0(3)r^2}=\dfrac{59.9}{r^2}$ V/m. $\ r>b$: $E=\dfrac{D}{\epsilon_0}=\dfrac{179.8}{r^2}$ V/m.`,
   R`<b>(c) Polarisation.</b> In the shell $\vec P=\epsilon_0(\epsilon_r-1)\vec E=\dfrac{\epsilon_r-1}{\epsilon_r}\dfrac{Q}{4\pi r^2}\hat r=\dfrac{1.06\times10^{-9}}{r^2}\hat r$. Bound surface charge is $\rho_{sb}=\vec P\cdot\hat n$, with $\hat n$ the <i>outward</i> normal of the dielectric: $-\hat r$ at $r=a$ and $+\hat r$ at $r=b$.<br>$\rho_{sb}(a)=-\dfrac{1.06\times10^{-9}}{(0.01)^2}=-10.6\ \mu$C/m², $\ \rho_{sb}(b)=+\dfrac{1.06\times10^{-9}}{(0.03)^2}=+1.18\ \mu$C/m².`,
   R`<b>Total bound charge.</b> $Q_b(a)=-10.6\times10^{-6}\cdot4\pi(0.01)^2=-13.3$ nC and $Q_b(b)=+1.18\times10^{-6}\cdot4\pi(0.03)^2=+13.3$ nC. Inside, $\rho_b=-\nabla\cdot\vec P=-\dfrac1{r^2}\dfrac{d}{dr}\big(r^2\cdot\tfrac{1.06\times10^{-9}}{r^2}\big)=0$. So the net bound charge of the shell is $-13.3+13.3=0$ ✓.`,
   R`<b>(d) Potential.</b> $V(a)=\int_a^\infty E\,dr=\int_a^bE_{shell}dr+\int_b^\infty E_{out}dr=\dfrac{Q}{4\pi\epsilon_0}\Big[\dfrac1{\epsilon_r}\Big(\dfrac1a-\dfrac1b\Big)+\dfrac1b\Big]$. With $\dfrac Q{4\pi\epsilon_0}=179.8$ V·m, $\dfrac1a=100$, $\dfrac1b=33.3$ m⁻¹: $V(a)=179.8\big[\tfrac13(66.7)+33.3\big]=179.8(55.6)=9.99\times10^3$ V.`],
   R`(a) $D=\dfrac{1.59\times10^{-9}}{r^2}$ for $r>a$. (b) $E=0,\ \dfrac{59.9}{r^2},\ \dfrac{179.8}{r^2}$ V/m. (c) $\rho_{sb}(a)=-10.6\ \mu$C/m², $\rho_{sb}(b)=+1.18\ \mu$C/m², total bound charge $0$. (d) $V(a)\approx\mathbf{10.0\ kV}$.`)},
]},
];
